import{_ as s,K as r,a as n,c as l,ac as a,b as t,q as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"中国象棋：漏看、失子与残局复盘","description":"用一个漏看炮架的例子，学会复原局面、比较候选着和给下一盘设定可执行目标。","frontmatter":{"title":"中国象棋：漏看、失子与残局复盘","description":"用一个漏看炮架的例子，学会复原局面、比较候选着和给下一盘设定可执行目标。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"中国象棋入门","summary":"用一个漏看炮架的例子，学会复原局面、比较候选着和给下一盘设定可执行目标。","status":"active","related":[{"title":"中国象棋：棋盘、走法与胜负规则","link":"/life/personal/chess/xiangqi/rules","kind":"棋类入门","scope":"general","audience":"general"},{"title":"中国象棋：双车、重炮与马后炮","link":"/life/personal/chess/xiangqi/mates","kind":"棋类入门","scope":"general","audience":"general"},{"title":"中国象棋：开局原则与常见布局","link":"/life/personal/chess/xiangqi/opening","kind":"棋类入门","scope":"general","audience":"general"}],"prev":{"text":"中国象棋：开局原则与常见布局","link":"/life/personal/chess/xiangqi/opening"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"中国象棋：开局原则与常见布局","link":"/life/personal/chess/xiangqi/opening"},"next":false},"headers":[],"relativePath":"life/personal/chess/xiangqi/review.md","filePath":"life/personal/chess/xiangqi/review.md"}'),d={name:"life/personal/chess/xiangqi/review.md"},p={class:"chess-example"},c={class:"chess-figure"};function h(b,e,_,g,f,u){const i=r("ArticleImage");return n(),l("div",null,[e[1]||(e[1]=a('<h1 id="中国象棋-漏看、失子与残局复盘" tabindex="-1">中国象棋：漏看、失子与残局复盘 <a class="header-anchor" href="#中国象棋-漏看、失子与残局复盘" aria-label="Permalink to &quot;中国象棋：漏看、失子与残局复盘&quot;">​</a></h1><p>复盘不是把最后输棋的那一步骂一遍，而是找到“从这里开始，我的判断变差了”。新手先复盘一个转折，不必把整盘几十回合都分析完。</p><h2 id="先留下能复原的记录" tabindex="-1">先留下能复原的记录 <a class="header-anchor" href="#先留下能复原的记录" aria-label="Permalink to &quot;先留下能复原的记录&quot;">​</a></h2><p>至少记下轮到谁走、所有棋子坐标、刚才的一步和你想达到的目的。截图可以保存位置，但最好补一句“红走，上一手黑车从 a8 到 a6”，否则隔一天常会忘记行动顺序。</p><p>本文坐标 a～i、1～10 从红方看。练习局面均为教学摆法，不是用户的实际战绩。</p><h2 id="一个典型失子-只看车-漏看炮" tabindex="-1">一个典型失子：只看车，漏看炮 <a class="header-anchor" href="#一个典型失子-只看车-漏看炮" aria-label="Permalink to &quot;一个典型失子：只看车，漏看炮&quot;">​</a></h2><p>摆红帅 e1、红兵 e5、红车 b4，黑将 e10、黑炮 b8、黑卒 b6，轮红走。其余点为空。e5 红兵隔开将帅。</p><p>你可能想“车吃卒还能向前进”，于是走红车 b4→b6，取走黑卒。结果呢？此时黑炮 b8 到 b6 的中间只有 b7，b7 空着，<strong>黑炮不能直接吃 b6 红车</strong> 。这不是一个丢车局面。</p><p>现在只改一个条件：另放一个黑卒在 b7。红车仍然可以从 b4 吃 b6 的黑卒，但吃完后，黑炮 b8 可以隔 b7 的黑卒吃 b6 红车。相同的起点和终点，因为多了一个炮架，结论完全不同。</p><p>复盘时要记录“漏看 b7 炮架”，而不是笼统写“太粗心”。下一盘才知道该检查什么。</p><h2 id="把候选着比较成一张表" tabindex="-1">把候选着比较成一张表 <a class="header-anchor" href="#把候选着比较成一张表" aria-label="Permalink to &quot;把候选着比较成一张表&quot;">​</a></h2>',11)),t("div",p,[t("div",c,[t("p",null,[o(i,{src:"/images/chess/xiangqi-review.svg",alt:"漏看炮架 · 吃卒前。红走；若车吃 b6，黑炮可隔 b7 回吃。"})])]),e[0]||(e[0]=a('<div class="chess-explanation"><p>在增加 b7 黑卒的局面中，可以比较三种想法：</p><table tabindex="0"><thead><tr><th>想法</th><th>对手的直接回应</th><th>初步判断</th></tr></thead><tbody><tr><td>车 b4 吃 b6</td><td>炮 b8 隔 b7 吃车</td><td>用车换卒，明显不合算</td></tr><tr><td>车 b4→a4</td><td>炮失去对 b4 的同路攻击目标</td><td>保车的候选，仍须检查新位置</td></tr><tr><td>先找其他有威胁着</td><td>要逐一写出变化</td><td>没算出来就不能写“反杀”</td></tr></tbody></table><p>车通常比一个兵卒重要，但子力价值不是机械分数。若存在强制将死，材料可以让位；若没有算到将死，就不能把漏看回吃解释成“弃子攻杀”。</p></div>',1))]),e[2]||(e[2]=a('<h2 id="到残局后先问四件事" tabindex="-1">到残局后先问四件事 <a class="header-anchor" href="#到残局后先问四件事" aria-label="Permalink to &quot;到残局后先问四件事&quot;">​</a></h2><p>先看帅是否安全，再看哪些子没有保护，然后看兵能否前进或过河，最后看有没有必须立即防守的将军。少子局面里每个子承担的任务更多，一步随意的帅移动也可能放开关键线路。</p><p>中国象棋的困毙算负，因此“我没有被将军”不代表安全。反复将军也不是无限拖延的方法；长将、长捉要按所用规则裁定。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ul><li>黑炮在 b8，红车在 b4，中间只有 b6 一个黑卒：黑炮能吃车吗？<strong>能。</strong> b5、b7 为空，恰好一个炮架。</li><li>红车吃到 b6 后，中间没有棋子，为什么反而暂时安全？<strong>炮吃子必须隔一子，距离远近本身不决定能否吃。</strong></li><li>一盘输了三辆大子，要同时改三个习惯吗？<strong>先选最常见的一种。</strong> 例如下盘每次落车前都扫描敌方车、炮、马的直接攻击。</li></ul><p>复盘笔记可写四行：“局面／原想法／漏掉的回应／下次检查”。能用棋盘证明原因，比给自己贴“不适合下棋”的标签更有效。</p><p>规则核对：<a href="https://www.wxf-xiangqi.org/images/wxf-rules/2018_World_XiangQi_Rules_English2018.pdf" target="_blank" rel="noopener noreferrer">WXF 规则</a>。</p>',7))])}const q=s(d,[["render",h]]);export{m as __pageData,q as default};
